char *getPermutation(int n, int k) {
  int fact[10];
  fact[0] = 1;
  for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;

  int nums[10];
  for (int i = 0; i < n; i++) nums[i] = i + 1;

  char *res = (char *)malloc(n + 1);
  k--;
  int len = n;
  for (int i = 0; i < n; i++) {
    int idx = k / fact[len - 1];
    res[i] = '0' + nums[idx];
    for (int j = idx; j < len - 1; j++) nums[j] = nums[j + 1];
    k %= fact[len - 1];
    len--;
  }
  res[n] = '\0';
  return res;
}

class Solution {
public:
  string getPermutation(int n, int k) {
    vector<int> fact(n + 1, 1);
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
    string nums;
    for (int i = 1; i <= n; i++) nums += to_string(i);
    string res;
    k--;
    for (int i = n; i >= 1; i--) {
      int idx = k / fact[i - 1];
      res += nums[idx];
      nums.erase(nums.begin() + idx);
      k %= fact[i - 1];
    }
    return res;
  }
};

func getPermutation(n int, k int) string {
	fact := make([]int, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * i
	}
	nums := make([]string, n)
	for i := 0; i < n; i++ {
		nums[i] = strconv.Itoa(i + 1)
	}
	var sb strings.Builder
	k--
	for i := n; i >= 1; i-- {
		idx := k / fact[i-1]
		sb.WriteString(nums[idx])
		nums = append(nums[:idx], nums[idx+1:]...)
		k %= fact[i-1]
	}
	return sb.String()
}

class Solution {
  public String getPermutation(int n, int k) {
    int[] fact = new int[n + 1];
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
    List<Integer> nums = new ArrayList<>();
    for (int i = 1; i <= n; i++) nums.add(i);
    StringBuilder sb = new StringBuilder();
    k--;
    for (int i = n; i >= 1; i--) {
      int idx = k / fact[i - 1];
      sb.append(nums.remove(idx));
      k %= fact[i - 1];
    }
    return sb.toString();
  }
}

class Solution:
    def getPermutation(self, n: int, k: int) -> str:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        nums = [str(i) for i in range(1, n + 1)]
        res = []
        k -= 1
        for i in range(n, 0, -1):
            idx = k // fact[i - 1]
            res.append(nums.pop(idx))
            k %= fact[i - 1]
        return "".join(res)

impl Solution {
  pub fn get_permutation(n: i32, k: i32) -> String {
    let n = n as usize;
    let mut fact = vec![1i32; n + 1];
    for i in 1..=n {
      fact[i] = fact[i - 1] * i as i32;
    }
    let mut nums: Vec<u8> = (1..=n as u8).map(|x| b'0' + x).collect();
    let mut k = k - 1;
    let mut res = String::new();
    for i in (1..=n).rev() {
      let idx = (k / fact[i - 1]) as usize;
      res.push(nums.remove(idx) as char);
      k %= fact[i - 1];
    }
    res
  }
}

const getPermutation = (n: number, k: number): string => {
  const fact: number[] = new Array(n + 1).fill(1);
  for (let i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
  const nums: string[] = [];
  for (let i = 1; i <= n; i++) nums.push(String(i));
  let res = '';
  k--;
  for (let i = n; i >= 1; i--) {
    const idx = Math.floor(k / fact[i - 1]);
    res += nums.splice(idx, 1)[0];
    k %= fact[i - 1];
  }
  return res;
};
